export const CLASS_ABILITIES = ['sentry', 'cloak', 'overcharge'] as const;
export const ABILITIES = {
  // rebuildSeconds: A Mechanic's sentry kit comes back this long after its sentry is destroyed.
  // dispenser: The sentry's dispenser: reach (m), health per second, and a share of each weapon's pickup ammo per second.
  sentry: { rebuildSeconds: 12, dispenser: { radius: 3.5, hps: 10, ammo: 0.25 } },
  // design: Cloak lasts `seconds` from full and recharges from empty in `rechargeSeconds`; firing breaks it.
  cloak: { seconds: 9, rechargeSeconds: 10 },
  // healing: Health a Medic heals to fill the overcharge.
  // seconds: How long it lasts.
  overcharge: { seconds: 6, healing: 300 },
} as const;

